/**
 * trimble-api.js — Trimble Connect Workspace API Connection
 * Copied from DDC-Statistics architecture.
 */
import { connect } from "trimble-connect-workspace-api";

// ── State ──
let api = null;
let viewer = null;

// ── Public API ──
export function getApi() { return api; }
export function getViewer() { return viewer; }

// ── Main Initialization ──
export async function initTrimble() {
  console.log("[TC Extension] Initializing...");
  
  // Check if we're inside an iframe (required for TC extension)
  const isInIframe = window.parent !== window;
  if (!isInIframe) {
    console.warn("[TC Extension] Not running inside an iframe. TC Workspace API requires iframe context.");
    alert("Cảnh báo: Đang chạy ngoài Trimble Connect (không nằm trong iframe).");
    return null;
  }

  try {
    // Connect with event callback — THE CORRECT WAY for TC Workspace API
    api = await connect(
      window.parent,
      (event, data) => {
        console.log("[TC Event]", event, data);
      },
      15000 // 15 second timeout
    );

    viewer = api.viewer;
    console.log("[TC Extension] Connected to Workspace API successfully");
    console.log("[TC Extension] API keys:", Object.keys(api));

    // Request access token permission (often required by TC)
    try {
      await api.extension.requestPermission("accesstoken");
      console.log("[TC Extension] Access token permission granted");
    } catch (e) {
      console.warn("[TC Extension] Permission request failed:", e.message || e);
    }

    return api;
  } catch (error) {
    console.error("[TC Extension] Connection failed:", error);
    if (error.message) console.error("[TC Extension] Lỗi:", error.message);
    alert("[TC Extension] Kết nối API thất bại: " + error);
    return null;
  }
}

// ── Process Model Objects ──
export async function processModelObjects(issuedAssemblies, btnIssue, renderReportCallback) {
  if (!api || !viewer) {
    await initTrimble();
    if (!api || !viewer) {
      alert("⚠️ Chưa kết nối được với mô hình Trimble.");
      if (btnIssue) btnIssue.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> Lỗi kết nối';
      return;
    }
  }

  try {
    if (btnIssue) btnIssue.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Đang phân tích...';
    let reportData = [];

    // Get objects
    const objects = await viewer.getObjects();
    
    if (!objects || objects.length === 0) {
      alert("[TC Extension] Mô hình đang trống hoặc chưa tải xong!");
      if (btnIssue) btnIssue.innerHTML = '<i class="fa-solid fa-paintbrush"></i> Thử lại';
      return;
    }

    console.log(`[TC Extension] Bắt đầu xử lý ${objects.length} đối tượng`);

    // Bước 1: Phủ xám mờ toàn bộ mô hình
    const allObjectIds = objects.map(obj => obj.id);
    await viewer.setColors([
      { color: { r: 200, g: 200, b: 200, a: 0.3 }, objectIds: allObjectIds }
    ]);

    let objectsToColorGreen = [];

    // Bước 2: Quét ID cấu kiện và đối chiếu
    for (const obj of objects) {
      const properties = await viewer.getObjectProperties(obj.id);
      
      let assemblyMark = properties.find(p => 
        p.name === 'Name' || p.name === 'Assembly mark' || p.name === 'Mark'
      )?.value;

      if (assemblyMark) {
        let isIssued = issuedAssemblies.includes(assemblyMark);
        reportData.push({ mark: assemblyMark, issued: isIssued });
        if (isIssued) objectsToColorGreen.push(obj.id);
      }
    }

    // Bước 3: Đè màu Xanh lên các cấu kiện
    if (objectsToColorGreen.length > 0) {
      await viewer.setColors([
        { color: { r: 16, g: 185, b: 129, a: 1 }, objectIds: objectsToColorGreen }
      ]);
    }
    
    // In báo cáo
    if (renderReportCallback) renderReportCallback(reportData);
    
    if (btnIssue) {
      btnIssue.classList.replace('bg-blue-600', 'bg-emerald-500');
      btnIssue.innerHTML = '<i class="fa-solid fa-check"></i> Đã tô màu!';
      setTimeout(() => { 
        btnIssue.classList.replace('bg-emerald-500', 'bg-blue-600');
        btnIssue.innerHTML = '<i class="fa-solid fa-paintbrush"></i> Cập nhật & Tô màu';
      }, 4000);
    }
  } catch (error) {
    console.error("[TC Extension] Lỗi khi xử lý mô hình:", error);
    if (btnIssue) btnIssue.innerHTML = '<i class="fa-solid fa-xmark"></i> Có lỗi xảy ra';
  }
}
